-- MARKER_E033_APPLY basic-gem-supply
-- ============================================================================
-- 18-gem-supply.sql (issue 155p, stage 1) — APPLY SOURCE
-- ============================================================================
-- Where basic's gems and gem-cutting recipes come from (design agreed with
-- Ritz, 2026-09-25; see issue 155p for every quote):
--
--   prospecting   copper and tin ore also give a cut +4 gem (Tourmaline,
--                 Zircon, Amber); mithril gives Outland's uncommon raw gems;
--                 thorium Outland's rare raw gems
--   Outland       every Outland monster (world and dungeon) can drop an
--                 uncut Wrath uncommon gem, rarely a rare one
--   epic gems     Kael'thas drops one uncut epic Wrath gem every kill, each
--                 world boss (Kazzak, Doomwalker) two, every other Outland
--                 dungeon boss one at 15%. Epic Wrath gems, uncut and cut,
--                 bind on pickup
--   recipes       the Wrath cutting recipes ("Design:" items) require
--                 Jewelcrafting 300. Uncommon-cut Designs drop in Outland's
--                 first half (Hellfire, Zangarmarsh, Terokkar, Nagrand),
--                 rare-cut Designs in the second (Blade's Edge,
--                 Netherstorm, Shadowmoon, the Isle), both in dungeons with
--                 the rare share rising along the dungeon ladder; about
--                 0.3% of kills drop one. Epic-cut Designs: every Outland
--                 boss, 1.5% of kills
--   Onyxia        her Ashen Sack of Gems becomes a hoard: 15–45 Gold Bars,
--                 vanilla's five coloured Sacks of Gems, five piles of
--                 low-level raw gems, three of Outland gems, two of Wrath
--                 gems; the binding epic gems (the stock three rolls and a
--                 pile of cut epic gems) drop from Onyxia herself, where
--                 those present can trade them for two hours
--
-- Rates Ritz hasn't set are defaults, logged in docs/balance-updates.md:
-- +4 gem 20% per copper/tin prospect, Outland uncommon 20% per mithril
-- prospect, Outland rare 4% per thorium prospect, Wrath uncommon 0.5% and
-- rare 0.05% per Outland kill.
--
-- Loot ids: this file owns reference tables 1550160–1550173 and the loot
-- rows whose Item is in 1550160–1550200; each apply first removes them and
-- restores what it saved, so re-applying is exact.
-- Database: acore_world_basic. Applied by E033, after E024 (the dungeon
-- templates), E027 (which removed recipes above 300) and E032 (the raised
-- Outland monsters, used here as "Outland's monsters").
-- ============================================================================

-- ---- 0. put back what an earlier apply changed ---------------------------------------
CREATE TABLE IF NOT EXISTS `basic_155p_design_skill` (
  `entry`             int unsigned      NOT NULL,
  `RequiredSkillRank` smallint unsigned NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='issue 155p: stock skill needed to learn each Wrath cutting Design, for the revert';
CREATE TABLE IF NOT EXISTS `basic_155p_bonding` (
  `entry`   int unsigned     NOT NULL,
  `bonding` tinyint unsigned NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='issue 155p: stock binding of the epic Wrath gems, for the revert';
CREATE TABLE IF NOT EXISTS `basic_155p_sack` LIKE `item_loot_template`;
ALTER TABLE `basic_155p_sack` COMMENT='issue 155p: the stock contents of the Ashen Sack of Gems (49294), for the revert';

UPDATE `item_template` i JOIN `basic_155p_design_skill` b ON b.`entry` = i.`entry` SET i.`RequiredSkillRank` = b.`RequiredSkillRank`;
UPDATE `item_template` i JOIN `basic_155p_bonding` b ON b.`entry` = i.`entry` SET i.`bonding` = b.`bonding`;
DELETE FROM `basic_155p_design_skill`;
DELETE FROM `basic_155p_bonding`;
-- the sack: our rows out, the saved stock rows back
DELETE FROM `item_loot_template` WHERE `Entry` = 49294 AND (SELECT COUNT(*) FROM `basic_155p_sack`) > 0;
INSERT IGNORE INTO `item_loot_template` SELECT * FROM `basic_155p_sack`;
DELETE FROM `basic_155p_sack`;
-- our loot rows and reference tables
DELETE FROM `creature_loot_template`    WHERE `Item` BETWEEN 1550160 AND 1550200;
DELETE FROM `prospecting_loot_template` WHERE `Item` BETWEEN 1550160 AND 1550200;
DELETE FROM `reference_loot_template`   WHERE `Entry` BETWEEN 1550160 AND 1550173;

