CREATE TABLE `tmp_155p_cuts` (`spell` int unsigned NOT NULL, `item` int unsigned NOT NULL, PRIMARY KEY (`spell`));
DROP TABLE IF EXISTS `tmp_155p_halves`;
CREATE TABLE `tmp_155p_halves` (`entry` int unsigned NOT NULL, `half` tinyint unsigned NOT NULL, PRIMARY KEY (`entry`));
