-- ---- 2. the gem families --------------------------------------------------------------
-- kind: plus4 (the level-55 cut +4 gems), low (vanilla low-level raw),
-- out_unc / out_rare (Outland raw), wr_unc / wr_rare / wr_epic (Wrath raw),
-- wr_epic_cut (cut epic Wrath gems). By exact stock name, so a renamed or
-- missing item shows up in the checks rather than silently.
DROP TABLE IF EXISTS `tmp_155p_gems`;
CREATE TABLE `tmp_155p_gems` (`item` int unsigned NOT NULL, `kind` varchar(12) NOT NULL, PRIMARY KEY (`item`));
INSERT INTO `tmp_155p_gems` SELECT `entry`, 'plus4' FROM `item_template`
WHERE `class` = 3 AND `name` IN ('Bold Tourmaline','Delicate Tourmaline','Teardrop Tourmaline','Runed Tourmaline','Bright Tourmaline',
  'Solid Zircon','Sparkling Zircon','Lustrous Zircon','Brilliant Amber','Smooth Amber','Rigid Amber','Gleaming Amber','Thick Amber');
INSERT INTO `tmp_155p_gems` SELECT `entry`, 'low' FROM `item_template`
WHERE `class` = 3 AND `name` IN ('Malachite','Tigerseye','Shadowgem','Small Lustrous Pearl','Moss Agate','Iridescent Pearl','Lesser Moonstone');
INSERT INTO `tmp_155p_gems` SELECT `entry`, 'out_unc' FROM `item_template`
WHERE `class` = 3 AND `name` IN ('Blood Garnet','Golden Draenite','Azure Moonstone','Deep Peridot','Shadow Draenite','Flame Spessarite');
INSERT INTO `tmp_155p_gems` SELECT `entry`, 'out_rare' FROM `item_template`
WHERE `class` = 3 AND `name` IN ('Living Ruby','Dawnstone','Star of Elune','Talasite','Nightseye','Noble Topaz');
INSERT INTO `tmp_155p_gems` SELECT `entry`, 'wr_unc' FROM `item_template`
WHERE `class` = 3 AND `name` IN ('Bloodstone','Sun Crystal','Chalcedony','Dark Jade','Shadow Crystal','Huge Citrine');
INSERT INTO `tmp_155p_gems` SELECT `entry`, 'wr_rare' FROM `item_template`
WHERE `class` = 3 AND `name` IN ('Scarlet Ruby','Autumn''s Glow','Sky Sapphire','Forest Emerald','Twilight Opal','Monarch Topaz');
INSERT INTO `tmp_155p_gems` SELECT `entry`, 'wr_epic' FROM `item_template`
WHERE `class` = 3 AND `name` IN ('Cardinal Ruby','King''s Amber','Majestic Zircon','Eye of Zul','Dreadstone','Ametrine');
-- cut epic Wrath gems: what the Jewelcrafting cuts make at item level 80, epic
INSERT IGNORE INTO `tmp_155p_gems` SELECT DISTINCT i.`entry`, 'wr_epic_cut' FROM `tmp_155p_cuts` c
JOIN `item_template` i ON i.`entry` = c.`item` WHERE i.`class` = 3 AND i.`GemProperties` <> 0 AND i.`Quality` = 4 AND i.`ItemLevel` = 80;

-- the Wrath cutting Designs, by the gem their recipe makes (uncommon cuts
-- are item level 70 uncommon, rare cuts 80 rare, epic cuts 80 epic)
DROP TABLE IF EXISTS `tmp_155p_designs`;
CREATE TABLE `tmp_155p_designs` (`item` int unsigned NOT NULL, `kind` varchar(8) NOT NULL, PRIMARY KEY (`item`));
INSERT IGNORE INTO `tmp_155p_designs`
SELECT d.`entry`, CASE WHEN g.`Quality` = 2 THEN 'unc' WHEN g.`Quality` = 3 THEN 'rare' ELSE 'epic' END
FROM `item_template` d
JOIN `tmp_155p_cuts` c ON c.`spell` = d.`spellid_2`
JOIN `item_template` g ON g.`entry` = c.`item`
WHERE d.`class` = 9 AND d.`subclass` = 10 AND g.`class` = 3 AND g.`GemProperties` <> 0
  AND ((g.`Quality` = 2 AND g.`ItemLevel` = 70) OR (g.`Quality` IN (3, 4) AND g.`ItemLevel` = 80))
  AND d.`name` NOT LIKE 'ZZOLD%';

-- ---- 3. reference tables (each a pick of one, at equal odds) -------------------------
-- 1550160 +4 cut gems      1550161 Outland uncommon raw   1550162 Outland rare raw
-- 1550163 Wrath uncommon   1550164 Wrath rare             1550165 Wrath epic (uncut)
-- 1550166 uncommon-cut Designs  1550167 rare-cut Designs   1550168 epic-cut Designs
-- hoard piles (one kind per pile): 1550170 low raw 8–12, 1550171 Outland 5–8,
-- 1550172 Wrath 5–7, 1550173 cut epic Wrath 6–10
INSERT INTO `reference_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT CASE g.`kind` WHEN 'plus4' THEN 1550160 WHEN 'out_unc' THEN 1550161 WHEN 'out_rare' THEN 1550162
                     WHEN 'wr_unc' THEN 1550163 WHEN 'wr_rare' THEN 1550164 ELSE 1550165 END,
       g.`item`, 0, 0, 0, 1, 1, 1, 1, CONCAT('basic 155p: ', g.`kind`)
FROM `tmp_155p_gems` g WHERE g.`kind` IN ('plus4','out_unc','out_rare','wr_unc','wr_rare','wr_epic');
INSERT INTO `reference_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT CASE d.`kind` WHEN 'unc' THEN 1550166 WHEN 'rare' THEN 1550167 ELSE 1550168 END,
       d.`item`, 0, 0, 0, 1, 1, 1, 1, CONCAT('basic 155p: ', d.`kind`, '-cut Design')
FROM `tmp_155p_designs` d;
INSERT INTO `reference_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT CASE WHEN g.`kind` = 'low' THEN 1550170 WHEN g.`kind` IN ('out_unc','out_rare') THEN 1550171
            WHEN g.`kind` IN ('wr_unc','wr_rare') THEN 1550172 ELSE 1550173 END,
       g.`item`, 0, 0, 0, 1, 1,
       CASE WHEN g.`kind` = 'low' THEN 8 WHEN g.`kind` IN ('out_unc','out_rare') THEN 5 WHEN g.`kind` IN ('wr_unc','wr_rare') THEN 5 ELSE 6 END,
       CASE WHEN g.`kind` = 'low' THEN 12 WHEN g.`kind` IN ('out_unc','out_rare') THEN 8 WHEN g.`kind` IN ('wr_unc','wr_rare') THEN 7 ELSE 10 END,
       CONCAT('basic 155p: hoard pile, ', g.`kind`)
FROM `tmp_155p_gems` g WHERE g.`kind` IN ('low','out_unc','out_rare','wr_unc','wr_rare','wr_epic_cut');

-- ---- 4. prospecting ----------------------------------------------------------------------
-- a loot row whose Reference is set rolls that table; Item is only its key
INSERT INTO `prospecting_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`) VALUES
  (2770,  1550160, 1550160, 20, 0, 1, 0, 1, 1, 'basic 155p: a +4 gem from copper'),
  (2771,  1550160, 1550160, 20, 0, 1, 0, 1, 1, 'basic 155p: a +4 gem from tin'),
  (3858,  1550161, 1550161, 20, 0, 1, 0, 1, 1, 'basic 155p: an Outland uncommon gem from mithril'),
  (10620, 1550162, 1550162,  4, 0, 1, 0, 1, 1, 'basic 155p: an Outland rare gem from thorium');

-- ---- 5. who drops what ------------------------------------------------------------------
-- loot tables of Outland's monsters: the world's raised monsters (E032)
-- with the half their spawns stand in, and the dungeons' templates (E024)
-- with their dungeon's place on the ladder (0 Hellfire Ramparts ... 1
-- Magisters' Terrace)
DROP TABLE IF EXISTS `tmp_155p_ladder`;
CREATE TABLE `tmp_155p_ladder` (`map_id` smallint unsigned NOT NULL, `step` tinyint unsigned NOT NULL, PRIMARY KEY (`map_id`));
INSERT INTO `tmp_155p_ladder` VALUES (543,0),(542,1),(547,2),(546,3),(557,4),(558,5),(560,6),(556,7),(269,8),(555,9),(540,10),(545,11),(554,12),(553,13),(552,14),(585,15);

DROP TABLE IF EXISTS `tmp_155p_loot`;
CREATE TABLE `tmp_155p_loot` (
  `lootid` int unsigned NOT NULL,
  `unc`    float        NOT NULL COMMENT 'chance of an uncommon-cut Design',
  `rare`   float        NOT NULL COMMENT 'chance of a rare-cut Design',
  PRIMARY KEY (`lootid`));
INSERT INTO `tmp_155p_loot` (`lootid`, `unc`, `rare`)
SELECT t.`lootid`, MAX(IF(h.`half` = 1, 0.3, IF(h.`half` = 3, 0.15, 0))), MAX(IF(h.`half` = 2, 0.3, IF(h.`half` = 3, 0.15, 0)))
FROM `basic_155k_world_templates` w
JOIN `creature_template` t ON t.`entry` = w.`entry`
JOIN `tmp_155p_halves` h ON h.`entry` = w.`entry`
WHERE t.`lootid` <> 0 GROUP BY t.`lootid`;
INSERT INTO `tmp_155p_loot` (`lootid`, `unc`, `rare`)
SELECT t.`lootid`, MAX(0.3 * (15 - l.`step`) / 15), MAX(0.3 * l.`step` / 15)
FROM `basic_155f_templates` s
JOIN `creature_template` t ON t.`entry` = s.`entry`
JOIN `creature` c ON c.`id` = s.`entry` AND (c.`spawnMask` & 1)
JOIN `tmp_155p_ladder` l ON l.`map_id` = c.`map`
WHERE t.`lootid` <> 0 GROUP BY t.`lootid`
ON DUPLICATE KEY UPDATE `unc` = GREATEST(`unc`, VALUES(`unc`)), `rare` = GREATEST(`rare`, VALUES(`rare`));

-- the bosses: normal-mode dungeon templates with a boss script (spawned or
-- summoned), and the two Outland world bosses
DROP TABLE IF EXISTS `tmp_155p_bosses`;
CREATE TABLE `tmp_155p_bosses` (`lootid` int unsigned NOT NULL, `epic_chance` float NOT NULL, `epic_rolls` tinyint unsigned NOT NULL, PRIMARY KEY (`lootid`));
INSERT IGNORE INTO `tmp_155p_bosses`
SELECT t.`lootid`, 15, 1 FROM `basic_155f_templates` s JOIN `creature_template` t ON t.`entry` = s.`entry`
WHERE t.`ScriptName` LIKE 'boss\_%' AND t.`lootid` <> 0;
INSERT INTO `tmp_155p_bosses` SELECT `lootid`, 100, 1 FROM `creature_template` WHERE `entry` = 24664 AND `lootid` <> 0   -- Kael'thas
ON DUPLICATE KEY UPDATE `epic_chance` = 100, `epic_rolls` = 1;
INSERT INTO `tmp_155p_bosses` SELECT `lootid`, 100, 2 FROM `creature_template` WHERE `entry` IN (18728, 17711) AND `lootid` <> 0   -- Kazzak, Doomwalker
ON DUPLICATE KEY UPDATE `epic_chance` = 100, `epic_rolls` = 2;

INSERT INTO `creature_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT `lootid`, 1550163, 1550163, 0.5,  0, 1, 0, 1, 1, 'basic 155p: uncut Wrath uncommon gem' FROM `tmp_155p_loot`
UNION ALL SELECT `lootid`, 1550164, 1550164, 0.05, 0, 1, 0, 1, 1, 'basic 155p: uncut Wrath rare gem' FROM `tmp_155p_loot`
UNION ALL SELECT `lootid`, 1550166, 1550166, `unc`,  0, 1, 0, 1, 1, 'basic 155p: uncommon-cut Design' FROM `tmp_155p_loot` WHERE `unc`  > 0
UNION ALL SELECT `lootid`, 1550167, 1550167, `rare`, 0, 1, 0, 1, 1, 'basic 155p: rare-cut Design'     FROM `tmp_155p_loot` WHERE `rare` > 0;
-- bosses: the epic gem (a loot row's MaxCount on a reference is how many
-- times it rolls), and the epic-cut Design at 1.5%
INSERT INTO `creature_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT `lootid`, 1550165, 1550165, `epic_chance`, 0, 1, 0, `epic_rolls`, `epic_rolls`, 'basic 155p: uncut epic Wrath gem' FROM `tmp_155p_bosses`
UNION ALL SELECT `lootid`, 1550168, 1550168, 1.5, 0, 1, 0, 1, 1, 'basic 155p: epic-cut Design' FROM `tmp_155p_bosses`
ON DUPLICATE KEY UPDATE `Chance` = VALUES(`Chance`);

-- ---- 6. recipes at 300, epic gems bind ---------------------------------------------------
INSERT INTO `basic_155p_design_skill` (`entry`, `RequiredSkillRank`)
SELECT i.`entry`, i.`RequiredSkillRank` FROM `item_template` i JOIN `tmp_155p_designs` d ON d.`item` = i.`entry`;
UPDATE `item_template` i JOIN `basic_155p_design_skill` b ON b.`entry` = i.`entry` SET i.`RequiredSkillRank` = LEAST(i.`RequiredSkillRank`, 300);

INSERT INTO `basic_155p_bonding` (`entry`, `bonding`)
SELECT i.`entry`, i.`bonding` FROM `item_template` i JOIN `tmp_155p_gems` g ON g.`item` = i.`entry` WHERE g.`kind` IN ('wr_epic', 'wr_epic_cut');
UPDATE `item_template` i JOIN `basic_155p_bonding` b ON b.`entry` = i.`entry` SET i.`bonding` = 1;

-- ---- 7. Onyxia's hoard -----------------------------------------------------------------
