-- the binding gems, from Onyxia herself (10 and 25 person): the stock epic
-- rolls (the stock uncut-epic table 10015: one sure, 60%, 30%) and a pile
-- of cut epic gems
INSERT INTO `creature_loot_template` (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`, `MinCount`, `MaxCount`, `Comment`)
SELECT t.`lootid`, x.`item`, x.`ref`, x.`chance`, 0, 1, 0, 1, 1, x.`note` FROM `creature_template` t
JOIN (SELECT 1550180 AS `item`, 10015 AS `ref`, 100 AS `chance`, 'basic 155p: epic gem, sure' AS `note`
      UNION ALL SELECT 1550181, 10015, 60,  'basic 155p: epic gem, 60%'
      UNION ALL SELECT 1550182, 10015, 30,  'basic 155p: epic gem, 30%'
      UNION ALL SELECT 1550183, 1550173, 100, 'basic 155p: pile of cut epic gems') x
WHERE t.`entry` IN (10184, 36538) AND t.`lootid` <> 0;

